contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint fundAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fundAmount, "not enough balance to fund");

        c.fallback{value: fundAmount}();

        uint cBalBefore = address(c).balance;
        uint ownerBalBefore = c.owner().balance;

        bool reverted;
        if (withdrawAmount <= cBalBefore) {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = true;
        }

        uint cBalAfter = address(c).balance;
        uint ownerBalAfter = c.owner().balance;

        assert(
            !reverted
                ? (ownerBalAfter == ownerBalBefore + withdrawAmount && cBalAfter == cBalBefore - withdrawAmount)
                : (cBalAfter == cBalBefore && ownerBalAfter == ownerBalBefore)
        );
    }

    receive() external payable {}
}

