contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint fundAmount, uint withdrawAmount) public payable {
        // The test contract must have enough Ether available to fund the contract.
        require(address(this).balance >= fundAmount, "not enough balance to fund");

        // Fund c. This is a top-level state-changing call on c.
        (bool funded,) = address(c).call{value: fundAmount}("");

        // Read the before-state through public surface only.
        uint cBalBefore = address(c).balance;
        address owner = c.owner();
        uint ownerBalBefore = owner.balance;

        // The deciding call, a plain top-level try statement on c.
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the after-state.
        uint cBalAfter = address(c).balance;
        uint ownerBalAfter = owner.balance;

        // General rule: success iff c held enough, and then exact transfer; otherwise no balance changes.
        if (cBalBefore >= withdrawAmount) {
            assert(!reverted);
            assert(ownerBalAfter == ownerBalBefore + withdrawAmount);
            assert(cBalAfter == cBalBefore - withdrawAmount);
        } else {
            assert(reverted);
            assert(ownerBalAfter == ownerBalBefore);
            assert(cBalAfter == cBalBefore);
        }
    }
}

