            c.fallback{value: amount}();
        }

        uint balBefore = address(c).balance;

        // Force msg.sender for calls to be an address different from owner.
        // We cannot change msg.sender directly since we are the caller;
        // c's owner is this test contract, so we need an indirect way.
        // Use a low-level call with a forged sender? Not possible.
        // Instead, the only way to have a non-owner caller is to not be owner.
        // But this test contract deployed C, so it is owner.
        // Therefore, the only way to test non-owner revert is to have another contract call.
        // Since we cannot deploy, we can use a cheatcode? No cheatcodes allowed.
        // Alternative: we can cause the owner to be changed? No setter.
        // Thus this rule cannot be tested from this test contract because it is always the owner.
        // We must choose a different rule.

        // Let's choose a different rule: fallback increments depositsCount and accepts Ether.
        // But that's already accepted.
        // Another rule: withdrawAll transfers entire balance to owner.
        // Let's test that: after withdrawAll, contract balance is 0 and owner balance increases.

        // But we need to ensure that we are owner, which we are.
        // So we can call withdrawAll.

        // However, the rule must be general for all inputs.
        // Let's set a balance and then call withdrawAll.

        // We already have balBefore from the fallback call.
        // Now call withdrawAll.

        uint ownerBalBefore = c.owner().balance; // c.owner() returns address

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint ownerBalAfter = c.owner().balance;

        // The general rule: if withdrawAll does not revert, then C's balance becomes 0 and the owner receives exactly the previous balance.
        // If it reverts, nothing changes.
        assert(reverted ? (balAfter == balBefore && ownerBalAfter == ownerBalBefore) : (balAfter == 0 && ownerBalAfter == ownerBalBefore + balBefore));
    }

    receive() external payable {}
}

